"""Generate configs/rnd_config.yaml for all Chokepoint sequences.

Walks the frame directory tree, matches each sequence to its annotation file,
and writes a complete rnd_config.yaml ready to run with ./compose.sh start -l.

Usage:
    python scripts/build_experiment_config.py
"""

import os
from pathlib import Path

FRAMES_ROOT = "/mnt/data/humoyun/chokepoint/frames"
ANNOTATION_ROOT = "volumes/src/annotation/chokepoint"
OUTPUT_CONFIG = "configs/rnd_config.yaml"

SHARED_SETTINGS = """\
# R&D pipeline configuration — auto-generated by scripts/build_experiment_config.py
gpu_id: 0
match_threshold: 0.3
partial_match_threshold: 0.15
db_path: "volumes/src/embeddings/main.pkl"
output_dir: "volumes/rnd_results"
client_slug: "rnd"
timezone: "UTC"
debug: false
eval: true
groundtruth_dir: "volumes/src/annotation/chokepoint/groundtruth"
minimum_face_size: 50
max_track_lifetime_seconds: 30
fps: 25
"""


def find_leaf_frame_dirs(frames_root: str) -> list[Path]:
    """Return all leaf directories (containing image files) under frames_root."""
    leaf_dirs = []
    for dirpath, dirnames, filenames in os.walk(frames_root):
        # A leaf dir has image files and no subdirs with images
        if not dirnames and any(
            f.lower().endswith((".jpg", ".jpeg", ".png", ".bmp"))
            for f in filenames
        ):
            leaf_dirs.append(Path(dirpath))
    return sorted(leaf_dirs)


def annotation_path(seq_id: str) -> str:
    """Derive the annotation file path from a sequence ID.

    Mirrors the frames directory structure:
      P1: P1E/P1E_S1/P1E_S1_C1/P1E_S1_C1.json
      P2: P2E/P2E_S1/P2E_S1_C1/P2E_S1_C1.1.json
    """
    portal_type = seq_id[:3]           # P1E, P1L, P2E, P2L
    session = seq_id[:6]               # P1E_S1, P2E_S3, etc.
    base_id = seq_id.rsplit(".", 1)[0] if "." in seq_id else seq_id
    return f"{ANNOTATION_ROOT}/{portal_type}/{session}/{base_id}/{seq_id}.json"


def cam_type(seq_id: str) -> str:
    portal_type = seq_id[:3]
    return "IN" if portal_type[2] == "E" else "OUT"


def build_entry(frame_dir: Path) -> dict | None:
    """Build a config entry for a frame dir, or None if annotation is missing."""
    seq_id = frame_dir.name  # e.g. P1E_S1_C1 or P2E_S1_C1.1
    ann = annotation_path(seq_id)

    if not os.path.exists(ann):
        return None

    return {
        "path": str(frame_dir),
        "annotation": ann,
        "camera_name": seq_id,
        "cam_type": cam_type(seq_id),
    }


def write_config(entries: list[dict], output_path: str) -> None:
    lines = [SHARED_SETTINGS, "videos:"]
    for e in entries:
        lines.append(f'  - path: "{e["path"]}"')
        lines.append(f'    annotation: "{e["annotation"]}"')
        lines.append(f'    camera_name: "{e["camera_name"]}"')
        lines.append(f'    cam_type: "{e["cam_type"]}"')
        lines.append("")
    Path(output_path).write_text("\n".join(lines))


def main() -> None:
    leaf_dirs = find_leaf_frame_dirs(FRAMES_ROOT)
    print(f"Found {len(leaf_dirs)} frame directories")

    entries, skipped = [], []
    for d in leaf_dirs:
        entry = build_entry(d)
        if entry:
            entries.append(entry)
        else:
            skipped.append(d.name)

    if skipped:
        print(f"Skipped {len(skipped)} (no annotation): {', '.join(skipped)}")

    write_config(entries, OUTPUT_CONFIG)
    print(f"Written {len(entries)} sequences → {OUTPUT_CONFIG}")

    # Quick breakdown by portal type
    from collections import Counter
    counts = Counter(e["camera_name"][:3] for e in entries)
    for portal, n in sorted(counts.items()):
        print(f"  {portal}: {n} sequences")


if __name__ == "__main__":
    main()
